const rayvnConfig = global.get('rayvnConfig') || {};
const logId = global.get('rayvnLogId');

if (!rayvnConfig.apiKey || !logId) {
    node.error('Rayvn not configured.');
    return null;
}

msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey
};

msg.url = `https://api.rayvn.global/logs/${logId}/entries`;

return msg;

const entries = msg.payload || [];

// Nothing to do
if (!Array.isArray(entries) || entries.length === 0) {
    msg.payload = [];
    return msg;
}

// Sort oldest to newest
entries.sort((a, b) => {
    return a.timeCreated - b.timeCreated;
});

// Track last forwarded entry per log
const logId = global.get('rayvnLogId') || 'default';
const key = `lastForwardedRayvnEntry_${logId}`;

const lastId = global.get(key);

// First run: set cursor but don't forward history
if (!lastId) {
    const latest = entries[entries.length - 1];
    global.set(key, latest.id);
    msg.payload = [];
    return msg;
}

// Collect entries after lastId
const newEntries = [];
let seen = false;

for (const entry of entries) {
    if (seen) newEntries.push(entry);
    if (entry.id === lastId) seen = true;
}

// If lastId not found, forward only latest
if (!seen) {
    const latest = entries[entries.length - 1];
    global.set(key, latest.id);
    msg.payload = [latest];
    return msg;
}

// Update cursor to newest forwarded
if (newEntries.length > 0) {
    global.set(key, newEntries[newEntries.length - 1].id);
}

msg.payload = newEntries;
return msg;

const entry = msg.payload;

// Skip if entry has the WaSOS label (prevents echo loop)
const WASOS_LABEL_ID = "8d8f4cd8-c57c-4ddd-861c-f515237c75d1";
if (entry.labels && entry.labels.some(label => label.id === WASOS_LABEL_ID)) {
    return null; // Skip this entry
}

// Skip system messages (no labels or system-generated text)
if (!entry.labels || entry.labels.length === 0) {
    // Additional check: skip if text contains system patterns
    if (entry.text.includes('har endret status') ||
        entry.text.includes('Loggen') ||
        entry.text.includes('er opprettet')) {
        return null;
    }
}

// Skip if no author name (Kan fjernes ved skalering)
if (!entry.loggedByFullName) {
    return null;
}

return msg;

const entry = msg.payload;

const chatroomName = global.get('wasosChatroomName');
const wasosUrl = global.get('wasos_url');
const wasosApiKey = global.get('wasos_apikey');

if (!chatroomName || !wasosUrl || !wasosApiKey) {
    node.error('WaSOS not configured');
    return null;
}

// Set headers (like your working Headers node)
msg.headers = {
    'x-api-key': wasosApiKey
};

// Set URL (like your working Headers node)
msg.url = `${wasosUrl}/api/chat/messages/${chatroomName}`;

// Build payload (like your working BuildSimpleChat) - DON'T stringify!
msg.payload = {
    "content": `[Rayvn - ${entry.loggedByFullName}] ${entry.text}`,
    "isLocation": false,
    "callsign": "Rayvn",  
    "replyMessageId": null,
    "files": []
};

return msg;

let wasosApiKey = global.get('wasos_apikey');
let rayvnConfig = global.get('rayvnConfig') || {};
let rayvnLogId = global.get('rayvnLogId');

if (!wasosApiKey || !rayvnConfig.apiKey || !rayvnLogId) {
    node.warn('Systemene er ikke fullstendig konfigurert for Rayvn → WaSOS.');
    return null;
}

return msg;
